-- LeadPilot schema (SQLite / local dev)
-- Generated by db/gen-schema.mjs from the live Postgres dump.
-- Executed automatically by src/lib/db.ts on first run.
CREATE TABLE IF NOT EXISTS appointments (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  lead_id TEXT,
  customer_name TEXT NOT NULL DEFAULT '',
  service TEXT NOT NULL DEFAULT '',
  starts_at TEXT NOT NULL,
  ends_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'booked',
  source TEXT NOT NULL DEFAULT 'ai',
  notes TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS audit_logs (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL DEFAULT '',
  user_id TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS automation_runs (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  automation_id TEXT NOT NULL DEFAULT '',
  automation_name TEXT NOT NULL DEFAULT '',
  trigger TEXT NOT NULL DEFAULT '',
  lead_id TEXT NOT NULL DEFAULT '',
  steps_json TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'ok',
  error TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS automations (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  name TEXT NOT NULL,
  trigger TEXT NOT NULL,
  steps_json TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS businesses (
  id TEXT NOT NULL,
  owner_user_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT 'My Business',
  industry TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  email TEXT NOT NULL DEFAULT '',
  website TEXT NOT NULL DEFAULT '',
  -- Structured business hours v1 JSON (version, timezone, status, days). Legacy free text is migrated to needs-configuration; no hours are inferred.
  hours_json TEXT NOT NULL DEFAULT '{}',
  settings_json TEXT NOT NULL DEFAULT '{}',
  onboarding_step INTEGER NOT NULL DEFAULT 0,
  onboarding_done INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS conversations (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  lead_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'ai',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS customers (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  email TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  opted_out INTEGER NOT NULL DEFAULT 0,
  tags TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS integrations (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'disconnected',
  config_json TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (id),
  UNIQUE (business_id,provider)
);
CREATE TABLE IF NOT EXISTS invoices (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  amount REAL NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'INR',
  status TEXT NOT NULL DEFAULT 'open',
  plan TEXT NOT NULL DEFAULT '',
  url TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS knowledge_entries (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'faq',
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS leads (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  email TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL DEFAULT 'website',
  service TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'New',
  score INTEGER NOT NULL DEFAULT 50,
  value REAL NOT NULL DEFAULT 0,
  urgency TEXT NOT NULL DEFAULT 'normal',
  intent TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  preferred_time TEXT NOT NULL DEFAULT '',
  quality TEXT NOT NULL DEFAULT 'warm',
  conversion_prob REAL NOT NULL DEFAULT 0.3,
  owner TEXT NOT NULL DEFAULT '',
  ai_summary TEXT NOT NULL DEFAULT '',
  next_followup_at TEXT,
  last_interaction_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS memberships (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'owner',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (business_id,user_id)
);
CREATE TABLE IF NOT EXISTS messages (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  conversation_id TEXT NOT NULL,
  sender TEXT NOT NULL,
  body TEXT NOT NULL,
  meta_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS review_requests (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  lead_id TEXT NOT NULL DEFAULT '',
  destination TEXT NOT NULL DEFAULT 'google',
  status TEXT NOT NULL DEFAULT 'sent',
  sent_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  opened_at TEXT,
  clicked_at TEXT,
  completed_at TEXT,
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS services (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  name TEXT NOT NULL,
  price REAL NOT NULL DEFAULT 0,
  duration_min INTEGER NOT NULL DEFAULT 30,
  description TEXT NOT NULL DEFAULT '',
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS subscriptions (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL,
  plan TEXT NOT NULL DEFAULT 'trial',
  status TEXT NOT NULL DEFAULT 'trialing',
  trial_ends_at TEXT,
  current_period_end TEXT,
  stripe_customer TEXT NOT NULL DEFAULT '',
  stripe_sub TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (business_id)
);
CREATE TABLE IF NOT EXISTS system_logs (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL DEFAULT '',
  level TEXT NOT NULL DEFAULT 'info',
  scope TEXT NOT NULL DEFAULT 'api',
  message TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS users (
  id TEXT NOT NULL,
  email TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'owner',
  email_verified INTEGER NOT NULL DEFAULT 0,
  verify_token TEXT,
  verify_expires TEXT,
  reset_token TEXT,
  reset_expires TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id),
  UNIQUE (email)
);
CREATE TABLE IF NOT EXISTS webhook_events (
  id TEXT NOT NULL,
  business_id TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL DEFAULT '',
  payload_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'ok',
  error TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (id)
);

